WITH valid_inventory AS (SELECT *, QUARTER(last_restock) AS last_restock_quarter FROM inventory WHERE last_restock BETWEEN '2025-07-01' AND '2025-07-15'), summary AS (SELECT product_id, ROUND(AVG(quantity), 2) AS avg_quantity, SUM(quantity) AS total_quantity FROM valid_inventory GROUP BY product_id) SELECT product_id, avg_quantity, total_quantity FROM summary ORDER BY total_quantity DESC
